import {
  countLeadingSpaces,
  escapeHtml,
  isBlankLine,
  normalizeNewlines,
  removeLeadingIndent,
  trimRightSpaces,
  trimSpaces,
} from './escape.mjs';
import { parseInline } from './inline.mjs';

export function markdownToHtml(source) {
  const normalized = normalizeNewlines(source);
  const lines = normalized.split('\n');
  return parseBlocks(lines, 0, lines.length).html;
}

function parseBlocks(lines, start, end) {
  const parts = [];
  let index = start;

  while (index < end) {
    if (isBlankLine(lines[index])) {
      index += 1;
      continue;
    }

    const htmlBlock = parseHtmlBlock(lines, index, end);
    if (htmlBlock) {
      parts.push(htmlBlock.html);
      index = htmlBlock.nextIndex;
      continue;
    }

    const atxHeading = parseAtxHeading(lines[index]);
    if (atxHeading) {
      parts.push(atxHeading);
      index += 1;
      continue;
    }

    const setextHeading = parseSetextHeading(lines, index, end);
    if (setextHeading) {
      parts.push(setextHeading.html);
      index = setextHeading.nextIndex;
      continue;
    }

    const hr = parseHorizontalRule(lines[index]);
    if (hr) {
      parts.push(hr);
      index += 1;
      continue;
    }

    const codeBlock = parseIndentedCodeBlock(lines, index, end);
    if (codeBlock) {
      parts.push(codeBlock.html);
      index = codeBlock.nextIndex;
      continue;
    }

    const blockquote = parseBlockquote(lines, index, end);
    if (blockquote) {
      parts.push(blockquote.html);
      index = blockquote.nextIndex;
      continue;
    }

    const list = parseList(lines, index, end);
    if (list) {
      parts.push(list.html);
      index = list.nextIndex;
      continue;
    }

    const paragraph = parseParagraph(lines, index, end);
    parts.push(paragraph.html);
    index = paragraph.nextIndex;
  }

  return {
    html: parts.join('\n'),
    nextIndex: index,
  };
}

function parseAtxHeading(line) {
  let index = 0;
  let indent = 0;
  while (index < line.length && indent < 4 && line[index] === ' ') {
    indent += 1;
    index += 1;
  }
  if (indent > 3 || line[index] !== '#') {
    return null;
  }

  let level = 0;
  while (index < line.length && line[index] === '#' && level < 6) {
    level += 1;
    index += 1;
  }

  if (level === 0) {
    return null;
  }

  if (index < line.length && line[index] !== ' ' && line[index] !== '\t') {
    return null;
  }

  let content = trimSpaces(line.slice(index));
  content = trimClosingHeadingHashes(content);
  return `<h${level}>${parseInline(content)}</h${level}>`;
}

function trimClosingHeadingHashes(text) {
  let end = text.length;
  while (end > 0 && (text[end - 1] === ' ' || text[end - 1] === '\t')) {
    end -= 1;
  }

  let hashEnd = end;
  while (hashEnd > 0 && text[hashEnd - 1] === '#') {
    hashEnd -= 1;
  }

  if (hashEnd === end) {
    return text.slice(0, end);
  }

  if (hashEnd > 0 && text[hashEnd - 1] !== ' ' && text[hashEnd - 1] !== '\t') {
    return text.slice(0, end);
  }

  while (hashEnd > 0 && (text[hashEnd - 1] === ' ' || text[hashEnd - 1] === '\t')) {
    hashEnd -= 1;
  }
