    html: `<h${level}>${parseInline(trimSpaces(lines[index]))}</h${level}>`,
    nextIndex: index + 2,
  };
}

function consumeSetextUnderline(line) {
  let index = 0;
  let indent = 0;
  while (index < line.length && indent < 4 && line[index] === ' ') {
    indent += 1;
    index += 1;
  }
  if (indent > 3 || index >= line.length) {
    return '';
  }

  const marker = line[index];
  if (marker !== '=' && marker !== '-') {
    return '';
