  let seenMarker = false;
  while (index < line.length) {
    const char = line[index];
    if (char === marker) {
      seenMarker = true;
      index += 1;
      continue;
    }
    if (char === ' ' || char === '\t') {
      index += 1;
      continue;
    }
    return '';
  }

  return seenMarker ? marker : '';
}

function parseHorizontalRule(line) {
  let index = 0;
  let indent = 0;
  while (index < line.length && indent < 4 && line[index] === ' ') {
    indent += 1;
    index += 1;
  }
  if (indent > 3 || index >= line.length) {
    return null;
  }

  const marker = line[index];
  if (marker !== '-' && marker !== '*' && marker !== '_') {
    return null;
  }

  let count = 0;
  while (index < line.length) {
    const char = line[index];
    if (char === marker) {
      count += 1;
      index += 1;
      continue;
