      const image = consumeLinkOrImage(text, index, true);
      if (image) {
        result += image.plainText;
        index = image.end;
        continue;
      }
    }

    if (char === '[') {
      const link = consumeLinkOrImage(text, index, false);
      if (link) {
        result += link.plainText;
        index = link.end;
        continue;
      }
